#[rustfmt::skip]
pub mod pb;
pub mod tls_client;

use std::path::Path;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

use server::runtime::{Config, ManualClock};

/// 2026-11-09T00:00:00Z, where test clocks start.
pub fn test_epoch() -> SystemTime {
    UNIX_EPOCH + Duration::from_secs(1_794_182_400)
}

/// A clock stopped at [`test_epoch`].
pub fn manual_clock() -> ManualClock {
    ManualClock::new(test_epoch())
}

/// Config text for a server whose data lives in `dir`, on a random local port.
pub fn config_text() -> String {
    r#"
server_id = "pi"
admin_username = "akhil"
listen_address = "127.0.0.1:0"
public_address = "relay.example:443"
database_path = "pi.sqlite"
key_dir = "keys"
"#
    .to_owned()
}

/// A config whose database and keys live in `dir`, on a random local port.
pub fn config_in(dir: &Path) -> Config {
    match Config::from_toml(&config_text(), dir) {
        Ok(config) => config,
        Err(error) => panic!("test config is invalid: {error}"),
    }
}
